use vstd::prelude::*;

verus! {
    // Linear search: return the first index where `a[idx] == e`,
    // or `a.len()` if `e` does not occur.
    fn linear_search(a: &Vec<i32>, e: i32) -> usize
        ensures
            // (1) result is in [0, a.len()]
            result <= a.len(),
            // (2) either we returned a.len() (not found)
            //     or we returned a position where a[result] == e
            result == a.len() || a[result] == e,
            // (3) for all k < result, a[k] != e
            forall |k: usize| k < result ==> a[k] != e,
    {
        let n = a.len();
        let mut idx: usize = 0;
        while idx < n
            invariant
                idx <= n,
                forall |k: usize| k < idx ==> a[k] != e,
            decreases n - idx,
        {
            // If we see the element, we immediately return its index.
            if a[idx] == e {
                return idx;
            }
            // Otherwise we know a[idx] != e, so we can extend the
            // "no-match" prefix by one.
            idx = idx + 1;
        }
        // If we fall out of the loop, idx == n and
        // ∀ k < n. a[k] != e, so returning n satisfies the spec.
        idx
    }
}

fn main() {
    // Example usage; not checked by Verus.
    let v = vec![3, 1, 4, 1, 5, 9];
    assert!(linear_search(&v, 1) == 1);
    assert!(linear_search(&v, 9) == 5);
    assert!(linear_search(&v, 2) == v.len());
}